{"tabIdentifier":"windowtab1","filePath":"Food Delivery/Food Delivery/Core/Utilities/VerificationResultStore.swift","content":"import Foundation

struct VerificationResultStore {
    private static let runIDKey = "benchmark.verification.runID"
    private static let armLabelKey = "benchmark.verification.armLabel"

    static func save(context: BenchmarkRunContext) {
        let defaults = UserDefaults.standard
        defaults.set(context.runID, forKey: runIDKey)
        defaults.set(context.armLabel, forKey: armLabelKey)
    }

    static func savedArmLabel(for runID: String) -> String? {
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: runIDKey) == runID else {
            return nil
        }
        return defaults.string(forKey: armLabelKey)
    }
}
"}

